KG42.register("edges-810a48055e1ca76e1e5bf96d",{"id":"S-04d7f02e567a8844","source":"KG31-8571e493b8ecf84a","type":"links","target":"KG31-e3df7b859b17cba0","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["11-p2p_mechanisms_evaluation"],"assertions":[{"id":"11-p2p_mechanisms_evaluation::v141-c-R001::E::v141-c-R001-E002","paper":"11-p2p_mechanisms_evaluation","rule_id":"v141-c-R001","rule_ref":"11-p2p_mechanisms_evaluation::v141-c-R001","record":{"edge_id":"v141-c-R001-E002","source":"pricing.local","target":"bidding.demand","type":"links","constraint_ids":["v141-c-R001-C003"],"evidence_ids":["v141-b-g07-ev-14","v141-b-g07-ev-15"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R001-C003"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"KG31-8571e493b8ecf84a","target":"KG31-e3df7b859b17cba0","source_occurrence_id":"11-p2p_mechanisms_evaluation::v141-c-R001::V::pricing.local","target_occurrence_id":"11-p2p_mechanisms_evaluation::v141-c-R001::V::bidding.demand","source_unit_id":"11-p2p_mechanisms_evaluation::v141-a-M01::pricing.local","target_unit_id":"11-p2p_mechanisms_evaluation::v141-a-M01::bidding.demand","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Appendix B's illustrated SDR interaction: Prosumer A's heater-demand schedule submitted to the coordinator. | Demand-bidding iteration under the paper's proposed last-defence mechanism. | Illustrated combined bid-count and ramping-rate step length control. | Iterative energy bidding using the bid-count form of step length control. | Proposed practical enforcement of ramping-rate step length control in P2P energy bidding. | Requested-energy bid updates in the iterative simulation's ramping-rate step length control. | Requested-energy quantities within SDR energy bids. | SDR bidding in the paper's two GB residential case-study sets, with accurate generation and demand forecasts assumed.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e22","v141-b-g03-E01","v141-b-g03-E02","v141-b-g03-E03","v141-b-g03-E04","v141-b-g03-E11","v141-b-g03-E15","v141-b-g04-EV07","v141-b-g07-ev-04","v141-b-g07-ev-14","v141-b-g07-ev-15"]},"active":true,"source_signature":"a63b01a874050a65bf4ca4c9868e88c794bc07d32cf5217be608c2c28dc93f0d","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"Internal prices are tariff-bounded functions of the zone supply-demand ratio, with distinct buying/selling roles for net power signs. For SDR above one both equal the export tariff; for SDR between zero and one retain the source nonlinear selling-price formula and buying-price cost/balance construction. Do not generalize denominator limits or fee accounting beyond source conditions.","target_definition":"The coordinator must reject requested-energy bids exceeding the prescribed ramping rate, thereby limiting demand-bid updates. Scope: Proposed practical enforcement of ramping-rate step length control in P2P energy bidding. Condition: The proposed enforcement rule is adopted and a bid exceeds the prescribed ramping rate. The coordinator limits demand-bid updates by uniformly randomly selecting participants whose energy bids must remain unchanged for that iteration. Scope: Iterative energy bidding using the bid-count form of step length control. Condition: Bid-count control is adopted; the restriction applies to participants selected for the forbidden-update set at the current iteration. Internal prices motivate updates to Prosumer A's submitted demand schedule to use excess local PV generation from Prosumer B. Scope: Appendix B's illustrated SDR interaction: Prosumer A's heater-demand schedule submitted to the coordinator. Condition: The unequal hourly internal buying prices in the illustrated iterations. Participants must submit their requested-energy quantities as part of the energy bids required at every iteration. Scope: Requested-energy quantities within SDR energy bids. The current requested-energy bid must lie within the previous bid plus or minus the ramping rate times the previous bid's absolute value. The resulting interval is clipped to the bid's lower and upper limits. Scope: Requested-energy bid updates in the iterative simulation's ramping-rate step length control. Condition: The ramping-rate form of step length control is adopted. Only rmp′ × 100% of energy bids may change, and each permitted demand-bid change is also restricted to ± rmp′ × 100%. Scope: Illustrated combined bid-count and ramping-rate step length control. Condition: The combined control with the broader ramping rate rmp′ is adopted. Demand bidding is assumed to be conducted on a day-ahead basis. Scope: SDR bidding in the paper's two GB residential case-study sets, with accurate generation and demand forecasts assumed. Demand-bidding iteration must terminate at the iteration limit, including when bids have not converged. Scope: Demand-bidding iteration under the paper's proposed last-defence mechanism. Condition: The predefined maximum iteration count is reached, whether or not convergence has been achieved.","constraints":[{"constraint_id":"v141-c-R001-C003","kind":"procedural","role":"core","statement":"Internal prices motivate updates to Prosumer A's submitted demand schedule to use excess local PV generation from Prosumer B. Scope: Appendix B's illustrated SDR interaction: Prosumer A's heater-demand schedule submitted to the coordinator. Condition: The unequal hourly internal buying prices in the illustrated iterations.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g07-ev-14","v141-b-g07-ev-15"]}],"evidence":[{"evidence_id":"v141-b-g07-ev-14","location":{"location_id":"src-d485825b0d-p28-c2r3__v141-a-M01-coordination","page":28,"printed_page":"1020","section":"Appendix B","anchor_text":"mes singular because the total electricity cost of Prosumer A is always the same ergence of the simu","equation_id":"B2-B6","figure_id":null,"table_id":null,"image_ref":"pages/page-28.png","occurrence_role":"example"},"source_text":"Assume that the initial schedule of Prosumer A is assumed to be\n\nP_{t=1,iter=0}^{EWH} = 2(\\text{kW}) \\quad \\text{and} \\quad P_{t=2,iter=0}^{EWH} = 4(\\text{kW}),  (B2)\n\nthen at 1st iteration, according to Formulae (A18)-(A23) in Appendix A, the internal buying prices will be\n\np_{t=1,iter=1}^{buying} = 5.03(\\text{pence/kWh}) \\quad \\text{and} \\quad p_{t=2,iter=1}^{buying} = 8.15(\\text{pence/kWh}).  (B3)\n\nDue to the fact that p_{t=1}^{buying} \u003c p_{t=2}^{buying}, according to Formula (B1), Prosumer A will reschedule the heater as\n\nP_{t=1,iter=1}^{EWH} = 4(\\text{kW}) \\quad \\text{and} \\quad P_{t=2,iter=1}^{EWH} = 2(\\text{kW}),  (B4)\n\nand send the schedule to the P2P energy sharing coordinator. Then 2nd iteration begins. The coordinator issues the new internal prices based on the schedule made at 1st iteration, being\n\np_{t=1,iter=2}^{buying} = 8.15(\\text{pence/kWh}) \\quad \\text{and} \\quad p_{t=2,iter=2}^{buying} = 5.03(\\text{pence/kWh}).  (B5)\n\nNow p_{t=1}^{buying} > p_{t=2}^{buying}, so Prosumer A reschedules the heater as\n\nP_{t=1,iter=2}^{EWH} = 2(\\text{kW}) \\quad \\text{and} \\quad P_{t=2,iter=2}^{EWH} = 4(\\text{kW}).  (B6)\n\nNote that the schedule becomes exactly the same as the initial schedule. Therefore, the mode in 1st and 2nd iteration will keep repeating in later iterations, and the simulation will never end (i.e. the simulation diverges), as illustrated in Figs. B1 and B2."},{"evidence_id":"v141-b-g07-ev-15","location":{"location_id":"src-d485825b0d-p29-c1r4__v141-a-M01-coordination","page":29,"printed_page":"1021","section":"Appendix B","anchor_text":"Note that the schedule becomes exactly the same as the initial schedule. The iterations, and the sim","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-29.png","occurrence_role":"definition"},"source_text":"Observing the iterative process of the above example (as showcased by Formulae (B2)-(B6) and illustrated in Figs. B1 and B2), it is seen that actually the SDR mechanism gave the right incentive signal every time (i.e. the internal prices motivated Prosumer A to change the schedule to use excess local PV generation from Prosumer B), but due to the discontinuity of the demand function, Prosumer A over-adjusted its power consumption every time, resulting in the oscillation-like divergence. Considering this fact, it is natural to be proposed to limit the change of power consumption of each prosumer for avoiding divergence. Therefore, now assume that at each iteration, Prosumer A is only allowed to at most make a ± 0.1 kW change to its schedule for each time slot. Also assume that Prosumer A will not change its schedule if no more cost can be saved. Keep all the other settings the same, and then run the simulation again. The results are shown in Figs. B3 and B4.\nFrom Figs. B3 and B4, it can be seen that gradually guided by the internal prices, the simulation converges after 10th iteration. Thanks to the limitation for the allowable power change at each iteration, Prosumer A does not over-adjust its power any longer, so oscillation does not happen and convergence is finally achieved. At the convergence, the power consumption of Prosumer A is completely supplied by the local PV generation of Prosumer B at both hours, resulting in perfect local energy balance and the least electricity cost of the whole P2P energy sharing community."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Appendix B's illustrated SDR interaction: Prosumer A's heater-demand schedule submitted to the coordinator. | Demand-bidding iteration under the paper's proposed last-defence mechanism. | Illustrated combined bid-count and ramping-rate step length control. | Iterative energy bidding using the bid-count form of step length control. | Proposed practical enforcement of ramping-rate step length control in P2P energy bidding. | Requested-energy bid updates in the iterative simulation's ramping-rate step length control. | Requested-energy quantities within SDR energy bids. | SDR bidding in the paper's two GB residential case-study sets, with accurate generation and demand forecasts assumed.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e22","v141-b-g03-E01","v141-b-g03-E02","v141-b-g03-E03","v141-b-g03-E04","v141-b-g03-E11","v141-b-g03-E15","v141-b-g04-EV07","v141-b-g07-ev-04","v141-b-g07-ev-14","v141-b-g07-ev-15"]},"source_record":{"edge_id":"v141-c-R001-E002","source":"pricing.local","target":"bidding.demand","type":"links","constraint_ids":["v141-c-R001-C003"],"evidence_ids":["v141-b-g07-ev-14","v141-b-g07-ev-15"]},"paper_scope_note":"SDR, MMR, and BS are kept separate; the A18 net quantity differs from the A24 independent component; optional step-size control and the divergent loop in the example are not treated as general convergence or necessary dependencies."}}],"assertion_ids":["11-p2p_mechanisms_evaluation::v141-c-R001::E::v141-c-R001-E002"]});
